package in.finseq.insurance;
import android.app.*;import android.content.*;import android.os.Build;import androidx.core.app.NotificationCompat;import org.json.*;
public class AttendanceReminderReceiver extends BroadcastReceiver{
 static final String CH="finseq_attendance";
 public void onReceive(Context c,Intent i){String a=i.getAction()==null?"SHIFT_REMINDER":i.getAction();if("SNOOZE".equals(a)){AttendanceReminderScheduler.snooze(c,10);log(c,"REMINDER_SNOOZED","10 minutes");return;}show(c,a);log(c,"REMINDER_DELIVERED",a);}
 void show(Context c,String kind){NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);if(nm==null)return;if(Build.VERSION.SDK_INT>=26)nm.createNotificationChannel(new NotificationChannel(CH,"Attendance reminders",NotificationManager.IMPORTANCE_HIGH));Intent open=new Intent(c,AttendanceActivity.class).putExtra("reminder_open",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP);PendingIntent op=PendingIntent.getActivity(c,7201,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Intent snooze=new Intent(c,AttendanceReminderReceiver.class).setAction("SNOOZE");PendingIntent sp=PendingIntent.getBroadcast(c,7202,snooze,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);String title="LATE_REMINDER".equals(kind)?"Attendance pending":"Office time reminder";String text="LATE_REMINDER".equals(kind)?"You have not completed Check-In. Open FINSEQ CMS to verify location/device and check in.":"Your shift is approaching. Open FINSEQ CMS when you reach office.";NotificationCompat.Builder b=new NotificationCompat.Builder(c,CH).setSmallIcon(android.R.drawable.ic_lock_idle_alarm).setContentTitle(title).setContentText(text).setStyle(new NotificationCompat.BigTextStyle().bigText(text)).setAutoCancel(true).setPriority(NotificationCompat.PRIORITY_HIGH).setContentIntent(op).addAction(0,"Open Attendance",op).addAction(0,"Snooze 10m",sp);nm.notify(7200,b.build());}
 static void log(Context c,String type,String status){new Thread(()->{try{ApiClient.post(c,"/api/attendance/mobile-event-json",new JSONObject().put("event_type",type).put("event_status",status).put("device_uid",AttendanceDevice.uid(c)).put("payload","alarm"));}catch(Exception ignored){}}).start();}
}